/* Pixel Temperature Converter - offline, no external assets */
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #0f3460;
  --highlight: #e94560;
  --text: #e0e0e0;
  --border: #533483;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: 'Courier New', Courier, monospace;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}
.card {
  background: var(--card);
  border: 4px solid var(--border);
  padding: 24px;
  max-width: 400px;
  width: 100%;
  box-shadow: 8px 8px 0 rgba(0,0,0,0.5);
  image-rendering: pixelated;
}
h1 {
  font-size: 1.4rem;
  text-align: center;
  margin: 0 0 20px;
  color: var(--highlight);
  text-transform: uppercase;
  letter-spacing: 2px;
  text-shadow: 2px 2px 0 #000;
}
.field { margin-bottom: 16px; }
label {
  display: block;
  margin-bottom: 6px;
  font-weight: bold;
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 1px;
}
input, select {
  width: 100%;
  padding: 10px 12px;
  font-family: inherit;
  font-size: 1rem;
  background: var(--bg);
  color: var(--text);
  border: 3px solid var(--border);
  outline: none;
  transition: border-color 0.1s, box-shadow 0.1s;
}
input:focus, select:focus {
  border-color: var(--highlight);
  box-shadow: 0 0 0 2px var(--highlight);
}
input:hover, select:hover { border-color: #7a5cbd; }
button {
  width: 100%;
  padding: 12px;
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 2px;
  background: var(--highlight);
  color: #fff;
  border: 3px solid #b03050;
  cursor: pointer;
  box-shadow: 4px 4px 0 #000;
  transition: transform 0.05s, box-shadow 0.05s, background 0.1s;
  margin-bottom: 16px;
}
button:hover { background: #ff5c7a; }
button:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}
button:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}
.result-box {
  display: flex;
  align-items: baseline;
  gap: 8px;
  background: var(--bg);
  border: 3px solid var(--border);
  padding: 12px;
}
.result-label {
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #a0a0b0;
}
#result {
  font-size: 1.6rem;
  font-weight: bold;
  color: var(--highlight);
  word-break: break-all;
}
.formula {
  margin: 16px 0 0;
  font-size: 0.8rem;
  text-align: center;
  color: #8888a0;
  line-height: 1.4;
}
@media (max-width: 400px) {
  .card { padding: 16px; }
  h1 { font-size: 1.2rem; }
}

// Pixel Temperature Converter logic
(function() {
  'use strict';

  var input = document.getElementById('temperature');
  var direction = document.getElementById('direction');
  var convertBtn = document.getElementById('convert');
  var resultEl = document.getElementById('result');

  function convert() {
    var raw = input.value.trim();
    if (raw === '') {
      resultEl.textContent = 'Error';
      return;
    }
    var num = Number(raw);
    if (!isFinite(num)) {
      resultEl.textContent = 'Error';
      return;
    }
    var result;
    if (direction.value === 'c-to-f') {
      result = num * 9 / 5 + 32;
    } else {
      result = (num - 32) * 5 / 9;
    }
    if (!isFinite(result)) {
      resultEl.textContent = 'Error';
      return;
    }
    resultEl.textContent = result.toFixed(2);
  }

  convertBtn.addEventListener('click', convert);

  input.addEventListener('keydown', function(e) {
    if (e.key === 'Enter') {
      convert();
    }
  });
})();
